const d = $input.first().json; const s = d.sections || {};
const sectionHtml = Object.entries(s).map(([k,v]) => '<h2>' + k.replace(/_/g,' ') + '</h2><div class="card">' + JSON.stringify(v?.data || v || {}) + '</div>').join('');
const html = '<!DOCTYPE html><html><head><style>body{font-family:Inter,sans-serif;margin:40px}h1{color:#37474f;border-bottom:3px solid #546e7a}h2{color:#455a64}.card{background:#eceff1;border-left:4px solid #546e7a;padding:16px;margin:12px 0}</style></head><body><h1>' + (d.report_type || 'Informe').replace(/_/g,' ') + '</h1>' + sectionHtml + '</body></html>';
return [{ json: { ...d, html_content: html } }];

const d = $input.first().json; const s = d.sections || {}; const meta = d.project_metadata || {};
const lines = ['# ' + (d.report_type || 'Informe').replace(/_/g,' '), '', '**Proyecto:** ' + (meta.project_id || 'N/A'), '**Generado:** ' + new Date().toISOString(), ''];
for (const [k,v] of Object.entries(s)) { lines.push('## ' + k.replace(/_/g,' '), '', '```json', JSON.stringify(v?.data || v || {}, null, 2), '```', ''); }
lines.push('---', '*DD Legal PMO*');
return [{ json: { html_content: d.html_content, md_content: lines.join('\n'), report_type: d.report_type } }];
